import numpy as np, datetime
def parse(path,n=500):
    ts=[];T=[]
    with open(path,'rb') as f:
        lines=f.read().decode(errors='replace').splitlines()[-n:]
    for ln in lines:
        c=ln.split('\t')
        if len(c)>=3:
            try: ts.append(int(c[0].split()[0])); T.append(float(c[-3]))
            except: pass
    return np.array(ts),np.array(T)
def hm(t): return datetime.datetime.fromtimestamp(t).strftime('%H:%M')
